(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.018+t*0.28)*18 + Math.cos(y*0.013-t*0.22)*12 + Math.sin((x+y)*0.009+t*0.15)*8;
  const wy = Math.cos(y*0.019-t*0.24)*18 + Math.sin(x*0.016+t*0.32)*12 + Math.cos((x-y)*0.011-t*0.18)*8;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.55)*110, 80+Math.cos(t*0.38)*55, 0.075, 2.1, 0.9],
    [320+Math.cos(t*0.48)*110, 160+Math.sin(t*0.65)*55, 0.095, 1.8, 1.1],
    [240+Math.sin(t*0.28+2)*150, 120+Math.cos(t*0.45+1)*95, 0.058, 2.4, 0.7],
    [120+Math.cos(t*0.75+1)*90, 180+Math.sin(t*0.58+3)*65, 0.11, 1.6, 1.3],
    [360+Math.sin(t*0.38+4)*100, 60+Math.cos(t*0.85+2)*75, 0.068, 2.7, 0.8],
    [240+Math.cos(t*0.32+5)*130, 200+Math.sin(t*0.52)*85, 0.085, 2.0, 1.0],
    [80+Math.sin(t*0.42+3)*70, 40+Math.cos(t*0.6+4)*50, 0.13, 1.4, 1.2],
    [400+Math.cos(t*0.35+1)*80, 210+Math.sin(t*0.48+2)*60, 0.072, 2.5, 0.85]
  ];
  let aS=0, iS=0, cS=0;
  for(const [sX,sY,f,sp,ph] of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const w1=Math.sin(d*f-t*sp+ph), w2=Math.sin(d*f*1.618-t*sp*0.618+ph*2);
    aS+=w1*0.7+w2*0.3;
    iS+=Math.sin(d*f*0.7+t*sp*0.55+ph*1.5)*0.8+Math.cos(d*f*0.5-t*sp*0.4+ph)*0.2;
    cS+=Math.sin(d*f*0.4+Math.atan2(sy-sY,sx-sX)*2-t*sp*0.3)*0.5;
  }
  const act=aS/8, inh=iS/8, cor=cS/8;
  const bg=(Math.sin(sx*0.035+sy*0.022+t*0.75)+Math.sin(sx*0.028-sy*0.038+t*1.05))/2
    +Math.sin((sx+sy)*0.11+t*2.3)*0.18+Math.sin((sx-sy)*0.095-t*1.9)*0.18
    +Math.sin(sx*0.06+t*1.5)*Math.sin(sy*0.06-t*1.2)*0.12;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
