  const cross=Math.sin(act*Math.PI*1.5)*Math.cos(inh*Math.PI)*0.3;
  const feed=Math.tanh((act-inh*0.65+bg*0.28+spiral+cor*0.4+cross)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.095+t)*0.45+Math.sin((sx*0.2+sy*0.15)+t*0.8)*0.2)*1.6)*0.28;
  const micro=Math.sin(sx*0.35+t*3)*Math.sin(sy*0.35-t*2.5)*0.06;
  const blend=feed*0.65+cell*0.25+micro, v=blend*0.5+0.5;
  const pal=[
    [6,12,52],[12,45,88],[18,85,115],[25,130,128],[45,165,130],
    [120,185,95],[195,190,60],[215,155,55],[210,110,65],[185,65,60],
    [140,35,55],[85,18,48],[35,10,42],[6,12,52]
