  const lum=0.82+Math.sin(feed*Math.PI)*0.18;
  const edge=Math.abs(feed)>0.65?1.12:Math.abs(feed)>0.4?1.04:0.96;
  const glow=Math.max(0,Math.abs(feed)-0.5)*0.15;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sm)*lum*edge+glow*40)|0),
